from pathlib import Path
import pandas as pd,json
R=Path(__file__).resolve().parents[1];S=R/'data/raw/submission_summary.txt.gz';n=dated=pre=later=0;scv=set();vars=set();labs=set();reviews=0
cols=['VariationID','ClinicalSignificance','DateLastEvaluated','Description','SubmittedPhenotypeInfo','ReportedPhenotypeInfo','ReviewStatus','CollectionMethod','OriginCounts','Submitter','SCV','SubmittedGeneSymbol','ExplanationOfInterpretation','SomaticClinicalImpact','Oncogenicity','ContributesToAggregateClassification']
for ch in pd.read_csv(S,sep='\t',comment='#',header=None,names=cols,dtype=str,chunksize=250000):
 n+=len(ch);d=pd.to_datetime(ch.DateLastEvaluated,errors='coerce');dated+=d.notna().sum();pre+=(d.dt.year<=2020).sum();later+=(d.dt.year>2020).sum();scv.update(ch.SCV.dropna().str.extract(r'(SCV\d+)')[0].dropna());vars.update(ch.VariationID.dropna());labs.update(ch.Submitter.dropna());reviews+=ch.ReviewStatus.fillna('').str.lower().str.contains('expert panel|practice guideline').sum()
out={'current_submission_rows':n,'unique_base_scv':len(scv),'unique_variations':len(vars),'submitters':len(labs),'dated_rows':int(dated),'evaluation_year_le2020':int(pre),'evaluation_year_gt2020':int(later),'expert_or_guideline_rows':int(reviews),'identifiability_pass':False,'blocker':'Current snapshot contains one current row per retained submission and last-evaluated date, but no historical assertion state at the 2020 cutoff, withdrawn assertion history, or former review status. Evaluation date cannot be used as prospective availability without leakage.'};(R/'results/temporal_identifiability.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
